import{_ as t}from"./chunks/第一步-03.D7lAR9Hu.js";import{_ as d,o,c as a,a2 as r}from"./chunks/framework.CqGPl1zp.js";const s="/newx-doc/assets/%E7%AC%AC%E4%B8%80%E6%AD%A5-01.Cn1Q0Amw.png",c="/newx-doc/assets/%E7%AC%AC%E4%B8%80%E6%AD%A5-02.Cn9JI_Xt.png",l="/newx-doc/assets/%E7%AC%AC%E4%BA%8C%E6%AD%A5-01.Cnka1VLO.png",i="/newx-doc/assets/mes-preview.BMu9P6Oc.png",E=JSON.parse('{"title":"功能开启","description":"","frontmatter":{},"headers":[],"relativePath":"mes/build.md","filePath":"mes/build.md","lastUpdated":null}'),m={name:"mes/build.md"};function p(n,e,u,_,h,b){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="功能开启" tabindex="-1">功能开启 <a class="header-anchor" href="#功能开启" aria-label="Permalink to &quot;功能开启&quot;">​</a></h1><p>进度说明：</p><ul><li>管理后台，请使用 <a href="https://gitee.com/yudaocode/yudao-ui-admin-vue3" target="_blank" rel="noreferrer">https://gitee.com/yudaocode/yudao-ui-admin-vue3</a> 仓库的 <code>master</code> 分支</li><li>后端项目，请使用 <a href="https://gitee.com/zhijiantianya/ruoyi-vue-pro" target="_blank" rel="noreferrer">https://gitee.com/zhijiantianya/ruoyi-vue-pro</a> 仓库的 <code>master</code>（JDK8）、<code>master-jdk17</code>（JDK17/21）或 <code>master-jdk25</code>（JDK25）分支</li></ul><p>MES 系统，后端由 <code>yudao-module-mes</code> 模块实现，前端由 <code>yudao-ui-admin-vue3</code> 的 <code>mes</code> 目录实现。</p><p>考虑到编译速度，默认 <code>yudao-module-mes</code> 模块是关闭的，需要手动开启。步骤如下：</p><ul><li>第一步，开启 <code>yudao-module-mes</code> 模块</li><li>第二步，导入 MES 系统的 SQL 数据库脚本</li><li>第三步，重启后端项目，确认功能是否生效</li></ul><h2 id="_1-第一步-开启模块" tabindex="-1">1. 第一步，开启模块 <a class="header-anchor" href="#_1-第一步-开启模块" aria-label="Permalink to &quot;1. 第一步，开启模块&quot;">​</a></h2><p>① 修改根目录的 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/pom.xml" target="_blank" rel="noreferrer"><code>pom.xml</code></a> 文件，取消 <code>yudao-module-mes</code> 模块的注释。如下图所示：</p><p><img src="'+s+'" alt="取消  模块的注释"></p><p>② 修改 <code>yudao-server</code> 目录的 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-server/pom.xml" target="_blank" rel="noreferrer"><code>pom.xml</code></a> 文件，引入 <code>yudao-module-mes</code> 模块。如下图所示：</p><p><img src="'+c+'" alt="引入  模块"></p><p>③ 点击 IDEA 右上角的【Reload All Maven Projects】，刷新 Maven 依赖。如下图所示：</p><p><img src="'+t+'" alt="刷新 Maven 依赖"></p><h2 id="_2-第二步-导入-sql" tabindex="-1">2. 第二步，导入 SQL <a class="header-anchor" href="#_2-第二步-导入-sql" aria-label="Permalink to &quot;2. 第二步，导入 SQL&quot;">​</a></h2><p>点击 <a href="https://lwb8832652.github.io/newx-doc/sql/mes.sql" target="_blank" rel="noreferrer">下载 SQL</a> 直接下载 SQL 文件，导入到数据库中。如下图所示：</p><p>友情提示：↑↑↑ mes.sql 是可以点击下载的！ ↑↑↑</p><p>重要说明：该 SQL 仅芋道星球成员可使用和商用，否则视为侵权（索赔 100 万，永久追溯）【下载即视为同意】。</p><p><img src="'+l+'" alt="导入数据库"></p><p>以 <code>mes_</code> 作为前缀的表，就是 MES 模块的表，一共 <strong>133</strong> 张，按业务模块分为：</p><table tabindex="0"><thead><tr><th>表前缀</th><th>模块</th><th>表数量</th></tr></thead><tbody><tr><td><code>mes_md_</code></td><td>基础数据</td><td>17</td></tr><tr><td><code>mes_pro_</code></td><td>生产管理</td><td>17</td></tr><tr><td><code>mes_wm_</code></td><td>仓库管理</td><td>62</td></tr><tr><td><code>mes_qc_</code></td><td>质量管理</td><td>16</td></tr><tr><td><code>mes_dv_</code></td><td>设备管理</td><td>12</td></tr><tr><td><code>mes_tm_</code></td><td>工具管理</td><td>2</td></tr><tr><td><code>mes_cal_</code></td><td>排班管理</td><td>7</td></tr></tbody></table><h2 id="_3-第三步-重启项目" tabindex="-1">3. 第三步，重启项目 <a class="header-anchor" href="#_3-第三步-重启项目" aria-label="Permalink to &quot;3. 第三步，重启项目&quot;">​</a></h2><p>重启后端项目，然后访问前端的 MES 菜单，确认功能是否生效。如下图所示：</p><p><img src="'+i+'" alt="确认功能是否生效"></p><p>至此，我们就成功开启了 MES 的功能 🙂</p><h2 id="_4-全局说明" tabindex="-1">4. 全局说明 <a class="header-anchor" href="#_4-全局说明" aria-label="Permalink to &quot;4. 全局说明&quot;">​</a></h2><p>① MES 各业务表中的 <code>code</code> 编码字段（如物料编码、工单编码等），均由编码规则模块自动生成，详见 <a href="./md/autocode">《【基础】编码规则》</a> 文档。</p><p>② MES 中存在大量一对多（主子表）关系的业务单据（如生产工单与 BOM 子表、采购入库与入库明细等）。通常的操作方式是：先新增主表记录，保存后在编辑弹窗中切换到对应的 Tab 页，再新增子表明细行。</p><p>③ MES 仓库管理模块的出入库单据统一采用<strong>两阶段处理流程</strong>：第一阶段为「单据起草」，负责创建业务单据并可配合审批流程；第二阶段为「执行入库/出库」，审批通过后执行库存操作，此时系统才会通过库存事务引擎生成事务流水并更新库存台账。系统还内置了一个<strong>虚拟线边库</strong>（编码 <code>WIP_VIRTUAL_WAREHOUSE</code>），用于统计在制物资的库存情况，详见 <a href="./wm/warehouse-setup">《【仓库】仓库与库区库位、条码赋码、SN码》</a>。</p>',28)])])}const A=d(m,[["render",p]]);export{E as __pageData,A as default};
